node -e "
const ExcelJS = require('./node_modules/exceljs');

async function createTable() {
  const wb = new ExcelJS.Workbook();
  wb.creator = 'NanoClaw Agent';

  const ws = wb.addWorksheet('משימות', {
    views: [{ rightToLeft: true }]
  });

  // Column definitions
  ws.columns = [
    { header: 'איש קשר', key: 'contact', width: 22 },
    { header: 'משימה / פעולה', key: 'task', width: 55 },
    { header: 'עדיפות', key: 'priority', width: 13 },
    { header: 'סטטוס', key: 'status', width: 13 },
    { header: 'תאריך יצירה', key: 'created', width: 15 },
    { header: 'תאריך ביצוע', key: 'due', width: 15 },
    { header: 'מקור', key: 'source', width: 16 },
    { header: 'הערות', key: 'notes', width: 35 },
  ];

  // Style the header row
  const headerRow = ws.getRow(1);
  headerRow.height = 28;
  headerRow.eachCell(cell => {
    cell.font = { bold: true, color: { argb: 'FFFFFFFF' }, size: 12 };
    cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF1F4E79' } };
    cell.alignment = { horizontal: 'center', vertical: 'middle', readingOrder: 'rightToLeft' };
    cell.border = {
      bottom: { style: 'thin', color: { argb: 'FF2E75B6' } }
    };
  });

  // Sample rows
  const rows = [
    { contact: 'דני כהן', task: 'לשלוח הצעת מחיר ללקוח', priority: 'גבוהה', status: 'לביצוע', created: '22.02.26', due: '01.03.26', source: 'Bama', notes: '' },
    { contact: 'מיכל לוי', task: 'מעקב אחרי פגישה ראשונית', priority: 'בינונית', status: 'בביצוע', created: '23.02.26', due: '05.03.26', source: 'WebAcademia', notes: 'לחזור אחרי שבוע' },
    { contact: 'יוסי גרין', task: 'לתאם הדגמת מוצר', priority: 'נמוכה', status: 'בהמתנה', created: '24.02.26', due: '10.03.26', source: 'Home', notes: 'ממתין לאישור לקוח' },
    { contact: 'רחל אברהם', task: 'שליחת חוזה לחתימה', priority: 'גבוהה', status: 'בוצע', created: '25.02.26', due: '28.02.26', source: 'Bama', notes: 'הושלם בזמן' },
    { contact: '', task: '', priority: '', status: '', created: '', due: '', source: '', notes: '' },
    { contact: '', task: '', priority: '', status: '', created: '', due: '', source: '', notes: '' },
    { contact: '', task: '', priority: '', status: '', created: '', due: '', source: '', notes: '' },
  ];

  // Status colors
  const statusColors = {
    'לביצוע': { bg: 'FF5B9BD5', text: 'FFFFFFFF' },
    'בביצוע': { bg: 'FFED7D31', text: 'FFFFFFFF' },
    'בהמתנה': { bg: 'FF767171', text: 'FFFFFFFF' },
    'בוצע':   { bg: 'FF70AD47', text: 'FFFFFFFF' },
  };

  // Priority colors
  const priorityColors = {
    'גבוהה':   { bg: 'FFFF0000', text: 'FFFFFFFF' },
    'בינונית': { bg: 'FFFFC000', text: 'FF000000' },
    'נמוכה':   { bg: 'FF00B050', text: 'FFFFFFFF' },
  };

  rows.forEach((rowData, i) => {
    const row = ws.addRow(rowData);
    row.height = 22;

    row.eachCell({ includeEmpty: true }, (cell, colNumber) => {
      cell.alignment = { vertical: 'middle', readingOrder: 'rightToLeft', wrapText: colNumber === 2 };
      // Alternating row color
      if (i % 2 === 0 && rowData.contact) {
        cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF2F2F2' } };
      }
    });

    // Color for status cell (col 4)
    if (rowData.status && statusColors[rowData.status]) {
      const statusCell = row.getCell(4);
      const c = statusColors[rowData.status];
      statusCell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: c.bg } };
      statusCell.font = { bold: true, color: { argb: c.text }, size: 10 };
      statusCell.alignment = { horizontal: 'center', vertical: 'middle' };
    }

    // Color for priority cell (col 3)
    if (rowData.priority && priorityColors[rowData.priority]) {
      const priCell = row.getCell(3);
      const c = priorityColors[rowData.priority];
      priCell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: c.bg } };
      priCell.font = { bold: true, color: { argb: c.text }, size: 10 };
      priCell.alignment = { horizontal: 'center', vertical: 'middle' };
    }
  });

  // Add autofilter
  ws.autoFilter = { from: 'A1', to: 'H1' };

  // Freeze the header row
  ws.views = [{ state: 'frozen', ySplit: 1, rightToLeft: true }];

  await wb.xlsx.writeFile('/workspace/agent/tasks_organized.xlsx');
  console.log('Done!');
}

createTable().catch(console.error);
"
